@startuml

class Ingredient {
  + name : string
  + measuringUnit : string
  + quantityInStock : float
}

class Dish {
  + name : string
  + numericIdentifier : int
}

class Table {
  + numericIdentifier : int
  + maximumAmountOfPeople : int
}

class Meal {
  + date : date
  + startTime : time
  + endTime : time
}

class Waiter {
  + numericIdentifier : int
  + name : string
  + address : string
  + phoneNumber : string
}

class Client {
  + taxIdentificationNumber : string
  + name : string
  + address : string
}

class MealDish {
}

class DishIngredient {
  + quantity : float
}

Dish "*" -- "*" Ingredient : contains
Dish "1" -- "*" DishIngredient
Ingredient "1" -- "*" DishIngredient
Meal "*" -- "1" Table : takes place at
Meal "*" -- "1" Waiter : is served by
Meal "0..1" -- "1" Client : consumed by
Meal "1" -- "*" MealDish
Dish "1" -- "*" MealDish

@enduml

